package com.paramichha.datafactory.generation;

import com.paramichha.datafactory.constraint.FieldConstraints;

import java.lang.reflect.Array;
import java.util.List;

/**
 * Produces typed array values — {@code int[]}, {@code String[]}, {@code MyClass[]}.
 *
 * <p>Size is determined by {@code @Size} bounds if present, otherwise 1–3 elements.
 * Elements are generated by delegating back to {@link DataGenerator} with the
 * component type.
 */
final class ArrayDataCreator implements DataCreator {

    static final ArrayDataCreator INSTANCE = new ArrayDataCreator();

    private ArrayDataCreator() {}

    @Override
    public boolean supports(Class<?> type) {
        return type != null && type.isArray();
    }

    @Override
    public Object shape(FieldConstraints field, BoundaryTarget target, DataMachine machine) {
        if ("null".equals(target.label())) return null;

        Class<?> arrayType     = field.fieldType();
        Class<?> componentType = arrayType.getComponentType();

        // Determine size from @Size bounds or default to 2
        int size = 2;
        if (field.hasBounds()) {
            long qty = target.targetQuantity() != null ? target.targetQuantity() : 2L;
            size = (int) Math.max(0, Math.min(qty, 10));
        }

        // Build component FieldConstraints — same name, component type, no annotations
        FieldConstraints componentField = FieldConstraints.builder(
                field.fieldName() + "Element", componentType).build();

        List<BoundaryTarget> componentTargets = BoundaryPlanner.plan(componentField);
        BoundaryTarget componentTarget = componentTargets.isEmpty()
                ? BoundaryTarget.semantic()
                : componentTargets.get(0);

        // Fill array
        Object arr = Array.newInstance(componentType, size);
        for (int i = 0; i < size; i++) {
            Object element = DataGenerator.shape(componentField, componentTarget, machine);
            if (element != null) {
                try { Array.set(arr, i, element); }
                catch (IllegalArgumentException e) {
                    // #9 — don't swallow silently; log so the mismatch is visible
                    System.err.println("DataFactory [WARN] ArrayDataCreator: cannot set element of type "
                            + element.getClass().getSimpleName() + " into " + componentType.getSimpleName()
                            + "[] for field '" + field.fieldName() + "' — slot left null. " + e.getMessage());
                }
            }
        }
        return arr;
    }
}
